'use client'

import { createContext, useContext, useEffect, useState, ReactNode } from 'react'
import { User } from '@/types'

interface AuthContextValue {
  token: string | null
  user: User | null
  login: (token: string, user: User) => void
  logout: () => void
  isAuthenticated: boolean
}

const AuthContext = createContext<AuthContextValue | null>(null)

export function AuthProvider({ children }: { children: ReactNode }) {
  const [token, setToken] = useState<string | null>(null)
  const [user, setUser] = useState<User | null>(null)

  useEffect(() => {
    const savedToken = sessionStorage.getItem('rl_token')
    const savedUser = sessionStorage.getItem('rl_user')
    if (savedToken && savedUser) {
      setToken(savedToken)
      setUser(JSON.parse(savedUser))
    }
  }, [])

  const login = (newToken: string, newUser: User) => {
    sessionStorage.setItem('rl_token', newToken)
    sessionStorage.setItem('rl_user', JSON.stringify(newUser))
    setToken(newToken)
    setUser(newUser)
  }

  const logout = () => {
    sessionStorage.removeItem('rl_token')
    sessionStorage.removeItem('rl_user')
    setToken(null)
    setUser(null)
  }

  return (
    <AuthContext.Provider value={{ token, user, login, logout, isAuthenticated: !!token }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error('useAuth must be used within AuthProvider')
  return ctx
}

import { Dataset, Review, ReviewsResponse, Summary, RateLimitStatus, ChatMessage } from '@/types'

const API_BASE = '/api/v1'

function getToken(): string | null {
  if (typeof window === 'undefined') return null
  return sessionStorage.getItem('rl_token')
}

async function apiFetch<T>(path: string, options: RequestInit = {}): Promise<T> {
  const token = getToken()
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...(options.headers as Record<string, string> || {}),
  }
  if (token) headers['Authorization'] = `Bearer ${token}`

  const res = await fetch(`${API_BASE}${path}`, { ...options, headers })

  if (res.status === 401) {
    sessionStorage.removeItem('rl_token')
    sessionStorage.removeItem('rl_user')
    window.location.href = '/login?expired=1'
    throw new Error('Unauthorized')
  }

  if (!res.ok) {
    const err = await res.json().catch(() => ({ message: 'Request failed' }))
    throw Object.assign(new Error(err.message || 'Request failed'), { status: res.status, data: err })
  }

  if (res.status === 204) return undefined as T
  return res.json()
}

// Auth
export const authApi = {
  login: (email: string, password: string) =>
    apiFetch<{ token: string; expires_at: string; user: { id: string; email: string } }>('/auth/login', {
      method: 'POST',
      body: JSON.stringify({ email, password }),
    }),
  logout: () => apiFetch<void>('/auth/logout', { method: 'POST' }),
}

// Datasets
export const datasetsApi = {
  list: () => apiFetch<{ datasets: Dataset[] }>('/datasets'),
  get: (id: string) => apiFetch<Dataset>(`/datasets/${id}`),
  create: (input: string) =>
    apiFetch<{ id: string; asin: string; status: string }>('/datasets', {
      method: 'POST',
      body: JSON.stringify({ input }),
    }),
  rescrape: (id: string) =>
    apiFetch<{ status: string }>(`/datasets/${id}/rescrape`, { method: 'POST' }),
  delete: (id: string) => apiFetch<void>(`/datasets/${id}`, { method: 'DELETE' }),
}

// Reviews & Summary
export const reviewsApi = {
  list: (id: string, params: Record<string, string | number>) => {
    const qs = new URLSearchParams(Object.entries(params).map(([k, v]) => [k, String(v)])).toString()
    return apiFetch<ReviewsResponse>(`/datasets/${id}/reviews?${qs}`)
  },
  summary: (id: string) => apiFetch<Summary>(`/datasets/${id}/summary`),
}

// Rate limit
export const scrapeApi = {
  rateLimit: () => apiFetch<RateLimitStatus>('/scrape/rate-limit'),
}

// Chat
export const chatApi = {
  send: (datasetId: string, message: string, history: ChatMessage[]) =>
    apiFetch<{ reply: string; scope_refused: boolean }>(`/datasets/${datasetId}/chat`, {
      method: 'POST',
      body: JSON.stringify({
        message,
        history: history.map(h => ({ role: h.role, content: h.content })),
      }),
    }),
}

